<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {RouterLink} from 'vue-router'
import type {Trip} from '@/types'
import {allRecords} from '@/services/planner.service'
import {tripGroup,type TripGroup} from '@/composables/tripPlanner'
import '@/styles/field-notes.css'
const trips=ref<Trip[]>([]),loading=ref(true),error=ref(''),search=ref(''),filter=ref('All trips'),failed=ref<Record<string,boolean>>({})
const groups:TripGroup[]=['Drafts','Upcoming','In progress','Past trips','Archived']
const visible=computed(()=>trips.value.filter(t=>(filter.value==='All trips'?t.status!=='archived':tripGroup(t)===filter.value)&&(t.title+' '+(t.destination||'')).toLowerCase().includes(search.value.toLowerCase())))
async function load(){loading.value=true;error.value='';try{trips.value=await allRecords<Trip>('trips')}catch{error.value='Your trips couldn’t be opened. Please try again.'}finally{loading.value=false}}
onMounted(load)
function dates(t:Trip){if(!t.start_date)return 'Dates undecided';const fmt=(s:string)=>new Date(s+'T00:00:00').toLocaleDateString('en',{month:'short',day:'numeric',year:'numeric'});return fmt(t.start_date)+(t.end_date&&t.end_date!==t.start_date?' – '+fmt(t.end_date):'')}
</script>
<template><main class="field-notes trip-collection"><header class="page-heading"><div><p class="eyebrow">Places & possibilities</p><h1>Trips<span>.</span></h1><p class="handnote">A little planning. Room for the unexpected.</p></div><RouterLink to="/trips/new" class="button primary">＋ Create trip</RouterLink></header><label class="trip-search"><span class="sr-only">Search trips</span><input v-model="search" type="search" placeholder="Find a trip or destination…" /></label><div class="filters" aria-label="Filter trips"><button v-for="g in ['All trips',...groups]" :key="g" :aria-pressed="filter===g" @click="filter=g">{{g}}</button></div><p class="muted status-explanation">Dates organize your plans. A manually set status takes priority; activities are completed only when you mark them.</p><div v-if="loading" class="loading" role="status">Gathering your journeys…</div><p v-else-if="error" class="notice" role="alert">{{error}} <button @click="load">Retry</button></p><template v-else-if="visible.length"><section v-for="g in groups.filter(g=>visible.some(t=>tripGroup(t)===g))" :key="g"><div class="section-heading"><h2>{{g}}</h2><span class="muted">{{visible.filter(t=>tripGroup(t)===g).length}} journeys</span></div><div class="trip-grid"><RouterLink v-for="trip in visible.filter(t=>tripGroup(t)===g)" :key="trip.id" :to="'/trips/'+trip.id" class="trip-ticket"><div v-if="trip.cover_image_path&&!failed[trip.id]" class="trip-cover"><img :src="trip.cover_image_path" :alt="trip.destination || trip.title" loading="lazy" @error="failed[trip.id]=true" /></div><div class="ticket-body"><span class="badge">{{tripGroup(trip)}}</span><p class="destination">{{trip.destination || 'Somewhere still to choose'}}</p><h3>{{trip.title}}</h3><p class="muted">{{dates(trip)}}</p><div class="ticket-footer"><span>Open itinerary</span><span aria-hidden="true">↗</span></div></div></RouterLink></div></section></template><section v-else class="empty"><p class="handnote">A blank page, an open road.</p><h2>{{search||filter!=='All trips'?'No trips found.':'Where would you like to go?'}}</h2><p>{{search||filter!=='All trips'?'Try another destination or clear your filters.':'Start with a name. Dates and plans can come later.'}}</p><button v-if="search||filter!=='All trips'" @click="search='';filter='All trips'">Clear filters</button></section></main></template>
<style scoped>.trip-collection h1 span{color:#879278}.trip-search{max-width:620px}.status-explanation{max-width:650px;margin-bottom:28px}.trip-grid{display:grid;gap:22px}.trip-ticket{display:flex;flex-direction:column;background:#fffbf2;border:1px solid #dbd0bd;border-radius:10px;overflow:hidden;box-shadow:0 5px 20px #5940270a}.trip-cover{aspect-ratio:2/1;background:#e0e3d6}.trip-cover img{width:100%;height:100%;object-fit:cover}.ticket-body{padding:24px;display:flex;flex-direction:column;flex:1;border-top:4px solid #9aa489}.destination{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#7d785f;margin:22px 0 8px;overflow-wrap:anywhere}.ticket-body h3{font-size:30px;margin:0 0 12px}.ticket-footer{margin-top:24px;padding-top:18px;border-top:1px dashed #cfc4af;display:flex;justify-content:space-between;color:#74283c;font-size:14px}.badge{align-self:flex-start}@media(min-width:680px){.trip-grid{grid-template-columns:1fr 1fr}}@media(min-width:1100px){.trip-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}</style>
